/**
 * R2Z2 Poller - "Tiered Scaling" Edition (v7.5)
 * Logic:
 * 1. Routine Poller:
 * - Growth: Dynamic Tiers based on KPM.
 * - <20 KPM: Cap 2 (Efficiency).
 * - >50 KPM: Cap 20 (Fast Ramp).
 * - >100 KPM: Cap 50 (Extreme/Instant).
 * - Low Activity: Probes with Batch 2 every 10s.
 * 2. Sequence Sync: Safety net every 60s for massive lag spikes.
 */

const Redis = require('ioredis');
const axios = require('axios');

// --- CONSTANTS ---
const STATIC = {
    BASE_URL: 'https://r2z2.zkillboard.com/ephemeral',
    SEQUENCE_URL: 'https://r2z2.zkillboard.com/ephemeral/sequence.json',
    KEYS: {
        PERF_LOG: 'r2z2:perf_log',
        SEQUENCE: 'r2z2:current_sequence',
        LAST_SEQ_FETCH: 'r2z2:last_sequence_fetch_time',
        HEARTBEAT: 'r2z2:ingestion.active',
        QUEUE: 'intel:queue:pending',
        SEEN_SET: 'r2z2:seen_killmails',
        METRICS: 'r2z2:metrics',
        BATCH_SIZE: 'r2z2:adaptive_batch_size',
        STREAK: 'r2z2:success_streak',
        GAP: 'r2z2:gap_streak'
    },
    MIN_SLEEP: 5000,
    PERF_LOG_MAX: 2000,
    USER_AGENT: 'Alfred-Intel-Bot/7.5 (Tiered-Scaling; contact: looknet)'
};

// --- HELPER: Smoothed KPM (15m window) ---
async function getRecentKpm(redis, lookback = 30) {
    const entries = await redis.lrange(STATIC.KEYS.PERF_LOG, 0, lookback - 1);
    if (entries.length === 0) return 0;
    let totalQueued = 0;
    let totalTimeMs = 0;
    for (const entry of entries) {
        try {
            const data = JSON.parse(entry);
            totalQueued += data.queued || 0;
            totalTimeMs += (data.sleep_ms || 0) + (data.dur_ms || 0);
        } catch {}
    }
    if (totalTimeMs === 0) return 0;
    const minutes = totalTimeMs / 60000;
    return minutes > 0 ? totalQueued / minutes : 0;
}

let redis;

async function fetchSequence(sequenceId) {
    try {
        const response = await axios.get(`${STATIC.BASE_URL}/${sequenceId}.json`, {
            timeout: 5000,
            headers: { 'User-Agent': STATIC.USER_AGENT, 'Accept': 'application/json' },
            validateStatus: () => true
        });
        return { sequenceId, status: response.status, data: response.status === 200 ? response.data : null };
    } catch (error) {
        return { sequenceId, status: 0, data: null, error: error.message };
    }
}

try {
    redis = new Redis({ host: 'redis', port: 6379, db: 0, connectTimeout: 5000 });
    await new Promise((resolve, reject) => {
        redis.on('ready', resolve);
        redis.on('error', reject);
        setTimeout(() => reject(new Error('Redis timeout')), 6000);
    });

    await redis.set(STATIC.KEYS.HEARTBEAT, new Date().toISOString(), 'EX', 300);

    let batchSize = parseInt(await redis.get(STATIC.KEYS.BATCH_SIZE) || '1'); 
    let successStreak = parseInt(await redis.get(STATIC.KEYS.STREAK) || '0');
    let gapStreak = parseInt(await redis.get(STATIC.KEYS.GAP) || '0');

    let currentSequence = await redis.get(STATIC.KEYS.SEQUENCE);
    if (!currentSequence) {
        const seqResp = await axios.get(STATIC.SEQUENCE_URL, { timeout: 5000, headers: { 'User-Agent': STATIC.USER_AGENT } });
        currentSequence = seqResp.data.sequence || seqResp.data.sequence_id;
        await redis.set(STATIC.KEYS.SEQUENCE, currentSequence);
        await redis.set(STATIC.KEYS.LAST_SEQ_FETCH, Date.now(), 'EX', 300);
    } else {
        currentSequence = parseInt(currentSequence);
    }

    const smoothedKpm = await getRecentKpm(redis, 30);
    const lastSeqFetch = await redis.get(STATIC.KEYS.LAST_SEQ_FETCH);
    const timeSinceLastFetch = lastSeqFetch ? (Date.now() - parseInt(lastSeqFetch)) : 999999;

    let mode = 'Flowing';
    let currentLag = 0;
    let isHugeCall = false;

    // --- SYSTEM 1: SEQUENCE SYNC (The Huge Call) ---
    // Only runs if 60s has passed naturally.
    if (timeSinceLastFetch >= 60000) {
        try {
            const seqResp = await axios.get(STATIC.SEQUENCE_URL, { timeout: 5000, headers: { 'User-Agent': STATIC.USER_AGENT } });
            const latestSequence = parseInt(seqResp.data.sequence || seqResp.data.sequence_id);
            await redis.set(STATIC.KEYS.LAST_SEQ_FETCH, Date.now(), 'EX', 300);

            const exactLag = latestSequence - currentSequence;
            currentLag = exactLag;

            if (exactLag > 10) {
                // This is the ONLY place we trigger a huge call
                batchSize = Math.min(50, exactLag);
                mode = 'HUGE CALL (Sync)';
                isHugeCall = true;
            } else if (exactLag > 0) {
                 batchSize = Math.min(50, exactLag);
                 mode = 'Edge Sync';
            } else {
                batchSize = 1;
                mode = 'At Tip';
            }
        } catch (err) {
            console.log(`[R2Z2] Seq check failed: ${err.message}`);
        }
    }

    const sequencesToFetch = Array.from({length: batchSize}, (_, i) => currentSequence + i);
    const fetchStart = Date.now();
    const results = await Promise.all(sequencesToFetch.map(fetchSequence));
    const fetchDur = Date.now() - fetchStart;
    results.sort((a, b) => a.sequenceId - b.sequenceId);

    const metrics = { found: 0, queued: 0, notFound: 0, errors: 0 };
    const killmailsToQueue = [];
    let highestSuccessfulSeq = currentSequence - 1;

    for (const result of results) {
        if (result.status === 200 && result.data) {
            metrics.found++;
            highestSuccessfulSeq = result.sequenceId;
            const km = result.data;
            const kmId = km.killmail_id || km.esi?.killmail_id;

            if (kmId && await redis.sadd(STATIC.KEYS.SEEN_SET, kmId)) {
                km.r2z2_sequence = result.sequenceId;
                km.r2z2_fetched_at = new Date().toISOString();
                killmailsToQueue.push(JSON.stringify(km));
                metrics.queued++;
            }
        } else if (result.status === 404) {
            metrics.notFound++;
        }
    }

    // --- TIP CONFIRMATION ---
    // If we hit a 404, delay the sequence check.
    if (metrics.notFound > 0) {
        await redis.set(STATIC.KEYS.LAST_SEQ_FETCH, Date.now(), 'EX', 300);
    }

    // --- SYSTEM 2: CONSERVATIVE POLLER ---
    // Logic: 5 successes at each step before going up.

    const newSequence = metrics.found > 0 ? highestSuccessfulSeq + 1 : currentSequence;
    let nextBatchSize = batchSize;
    let nextSuccessStreak = successStreak;
    let nextGapStreak = gapStreak;
    let sleepTime = STATIC.MIN_SLEEP;

    // CASE A: Perfect Run (All Found)
    if (metrics.found > 0 && metrics.notFound === 0) {
        if (!isHugeCall) { 
            nextSuccessStreak++;
            nextGapStreak = 0;

            // DYNAMIC SCALING TIERS
            // Adapts capacity and reaction speed based on KPM
            let batchCap = 2;       // Default: Efficiency Gate
            let requiredStreak = 5; // Default: Stable
            let growthStep = 1;     // Default: Linear

            if (smoothedKpm > 100) {
                batchCap = 50;      // Extreme Load
                requiredStreak = 1; // Instant Reaction
                growthStep = 5;     // Fast Ramp
            } else if (smoothedKpm > 50) {
                batchCap = 20;      // Heavy Load
                requiredStreak = 3; // Fast Response
                growthStep = 2;
            } else if (smoothedKpm > 20) {
                batchCap = 5;       // Standard Active
                requiredStreak = 5;
                growthStep = 1;
            }

            if (nextSuccessStreak >= requiredStreak) {
                if (batchSize < batchCap) {
                    nextBatchSize = Math.min(batchCap, batchSize + growthStep);
                    nextSuccessStreak = 0; 
                } else {
                    // Check if we need to scale down (e.g. KPM dropped)
                    nextBatchSize = Math.min(batchSize, batchCap);
                }
            } else {
                // Ensure we respect the cap during streak buildup
                nextBatchSize = Math.min(batchSize, batchCap);
            }
        } else {
             // After a huge call, reset to a safe active level (5 or 2)
             nextBatchSize = (smoothedKpm > 20) ? 5 : 2; 
             nextSuccessStreak = 0;
        }
    } 
    // CASE B: Soft Fail (Found Some, Missed Some) - The Edge
    else if (metrics.found > 0 && metrics.notFound > 0) {
        // REQUESTED: Ask for 2 every 10 seconds (Better Soft Fail condition)
        nextBatchSize = 2; 
        nextSuccessStreak = 0;
        nextGapStreak = 0;

        sleepTime = 10000; // Fixed 10s for heavy probe
        mode = 'Soft Fail (Probe 2 @ 10s)';
    } 
    // CASE C: Hard Fail (Found Nothing)
    else {
        // REQUESTED: Ask for 2 every 10 seconds
        nextBatchSize = 2;
        nextSuccessStreak = 0;
        nextGapStreak++;

        // Base 10s + Backoff
        const backoff = Math.min(10000, nextGapStreak * 1000);
        sleepTime = 10000 + backoff;
        mode = `Backing Off (2 @ ${sleepTime/1000}s)`;
    }

    await redis.set(STATIC.KEYS.SEQUENCE, newSequence);
    await redis.set(STATIC.KEYS.BATCH_SIZE, nextBatchSize);
    await redis.set(STATIC.KEYS.STREAK, nextSuccessStreak);
    await redis.set(STATIC.KEYS.GAP, nextGapStreak);

    if (killmailsToQueue.length > 0) {
        const pipe = redis.pipeline();
        for (const km of killmailsToQueue) pipe.rpush(STATIC.KEYS.QUEUE, km);
        await pipe.exec();
    }

    const mp = redis.pipeline();
    mp.hincrby(STATIC.KEYS.METRICS, 'total_fetched', metrics.found);
    mp.hincrby(STATIC.KEYS.METRICS, 'total_queued', metrics.queued);
    mp.hset(STATIC.KEYS.METRICS, 'last_sequence', newSequence);
    mp.hset(STATIC.KEYS.METRICS, 'current_batch_size', nextBatchSize);
    mp.hset(STATIC.KEYS.METRICS, 'current_kpm', smoothedKpm.toFixed(2));
    mp.hset(STATIC.KEYS.METRICS, 'last_run', new Date().toISOString());
    await mp.exec();

    const perfEntry = JSON.stringify({
        ts: new Date().toISOString(),
        batch: batchSize,
        found: metrics.found,
        queued: metrics.queued,
        not_found: metrics.notFound,
        dur_ms: fetchDur,
        sleep_ms: sleepTime,
        seq: currentSequence,
        kpm: smoothedKpm.toFixed(1),
        lag: currentLag,
        mode: mode,
        streak: nextSuccessStreak
    });

    const perfPipe = redis.pipeline();
    perfPipe.lpush(STATIC.KEYS.PERF_LOG, perfEntry);
    perfPipe.ltrim(STATIC.KEYS.PERF_LOG, 0, STATIC.PERF_LOG_MAX - 1);
    await perfPipe.exec();

    if (sleepTime > 0) await new Promise(r => setTimeout(r, sleepTime));
    await redis.set(STATIC.KEYS.HEARTBEAT, new Date().toISOString(), 'EX', 300);

    return [{ json: {
        status: 'success',
        sequence: newSequence,
        batch: nextBatchSize,
        sleep_ms: sleepTime,
        kpm: smoothedKpm,
        mode: mode,
        found: metrics.found,
        should_restart: true
    }}];

} catch (error) {
    console.error('[R2Z2] Error:', error.message);
    try { if (redis) await redis.del(STATIC.KEYS.HEARTBEAT); } catch {}
    await new Promise(r => setTimeout(r, 5000));
    return [{ json: { status: 'error', error: error.message, should_restart: true }}];
} finally {
    if (redis) await redis.quit();
}

const Redis = require('ioredis');
let redis;

try {
    redis = new Redis({ host: 'redis', port: 6379, db: 0, connectTimeout: 5000 });

    await new Promise((resolve, reject) => {
        redis.on('ready', resolve);
        redis.on('error', reject);
        setTimeout(() => reject(new Error('Redis connection timeout')), 6000);
    });

    console.log('[Activity Check] Connected to Redis.');

    // Check if ingestion.active exists
    const isActive = await redis.get('r2z2:ingestion.active');

    if (isActive) {
        const ttl = await redis.ttl('r2z2:ingestion.active');
        console.log(`[Activity Check] Ingestion is ACTIVE. Last update: ${isActive}, TTL: ${ttl}s`);
    } else {
        console.log('[Activity Check] Ingestion is INACTIVE (key expired or missing).');
    }

    return [{ json: { 
        ingestion_active: !!isActive,
        last_update: isActive,
        ttl_remaining: isActive ? await redis.ttl('r2z2:ingestion.active') : 0
    }}];

} catch (error) {
    console.error('[Activity Check] Redis error:', error.message);
    // On error, assume ingestion is inactive to allow restart
    return [{ json: { 
        ingestion_active: false,
        error: error.message 
    }}];

} finally {
    if (redis) {
        await redis.quit();
        console.log('[Activity Check] Redis connection closed.');
    }
}
